"use client";

import SkeletonRow from "@/app/dashboard/admin/categories/SkeletonRow";
import { useState, useEffect } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { useCategories } from "@/hooks/useCategories";
import debounce from "lodash.debounce";
import Image from "next/image";
import Pagination from "@/components/products/Pagination"; // ✅ Import Pagination Component

const CategoryTable = () => {
  const searchParams = useSearchParams();
  const router = useRouter();

  // Get current page & search query from URL
  const currentPage = Number(searchParams.get("page")) || 1;
  const searchQueryFromURL = searchParams.get("search") || "";
  const [searchQuery, setSearchQuery] = useState(searchQueryFromURL);
  const pageSize = 10;

  // Function to update URL parameters properly
  const updateQueryParams = (newParams: { page?: number; search?: string }) => {
    const params = new URLSearchParams(searchParams.toString()); // Clone existing params

    if (newParams.page !== undefined) {
      if (newParams.page === 1) {
        params.delete("page"); // Remove 'page' if it's 1
      } else {
        params.set("page", String(newParams.page)); // Set page if it's >1
      }
    }

    if (newParams.search !== undefined) {
      if (newParams.search.trim() === "") {
        params.delete("search"); // Remove 'search' if it's empty
      } else {
        params.set("search", newParams.search);
      }
    }

    const newUrl = `/dashboard/admin/categories${params.toString() ? "?" + params.toString() : ""}`;
    router.push(newUrl);
  };
  
  // Debounced search function to update URL
  const debouncedUpdateQueryParams = debounce((search: string) => {
    updateQueryParams({ search, page: 1 }); // Reset to page 1 on search
  }, 500); // 500ms delay

  // Effect to trigger debounced update when search input changes
  useEffect(() => {
    debouncedUpdateQueryParams(searchQuery);
  }, [searchQuery]);

  const { data, isLoading, isError } = useCategories(currentPage, pageSize, searchQueryFromURL);

  return (
    <div>
      {/* Search Bar */}
      <input
        type="text"
        placeholder="Search categories..."
        value={searchQuery}
        onChange={(e) => setSearchQuery(e.target.value)}
        className="border p-2 mb-4"
      />

      {/* Table */}
      <table className="border-collapse border border-gray-300 w-full">
        <thead>
          <tr className="bg-gray-200">
            <th className="border p-2 text-gray-400">Category Picture</th>
            <th className="border p-2 text-gray-400">Category Name</th>
          </tr>
        </thead>
        <tbody>
          {isLoading
            ? Array.from({ length: 10 }).map((_, index) => <SkeletonRow key={index} />)
            : data?.content?.map((category) => (
                <tr key={category.categoryId}>
                  <td className="border p-2 text-gray-400">
                    <div className="w-[50px] h-[50px] flex items-center justify-center overflow-hidden rounded">
                      <Image
                        src={category.categoryPicture}
                        alt={category.categoryName}
                        width={50}
                        height={50}
                        className="rounded object-cover"
                        unoptimized
                      />
                    </div>
                  </td>
                  <td className="border p-2 text-gray-400">{category.categoryName}</td>
                </tr>
              ))}
        </tbody>
      </table>

      {/* Pagination */}
      {!isLoading && data && (
        <Pagination
          currentPage={currentPage}
          totalPages={data.totalPages || 1}
          setCurrentPage={(page) => updateQueryParams({ page })} // ✅ Fixed pagination issue
        />
      )}
    </div>
  );
};

export default CategoryTable;
